<?php
if (!defined('ABSPATH')) exit;
add_shortcode('uem_payment_checkout','uem_render_payment_checkout');
function uem_render_payment_checkout(){if(!is_user_logged_in())return '<p>Please log in before paying.</p>';$event_id=absint($_GET['ev_id']??0);$tiers=uem_active_ticket_tiers($event_id);if(!$tiers)return '<p>No paid tickets are currently available.</p>';if(isset($_POST['uem_begin_payment'])&&wp_verify_nonce($_POST['uem_payment_nonce']??'','uem_begin_payment_'.$event_id)){$order=uem_payment_create_order($event_id,get_current_user_id(),sanitize_text_field($_POST['ticket_code']??''));if(is_wp_error($order))return '<p>'.esc_html($order->get_error_message()).'</p>';return uem_netopia_v2_checkout($order);}ob_start();?><div style="max-width:720px;margin:35px auto;padding:28px;background:#fff;border:1px solid #e5e7eb;border-radius:16px"><h2>Choose your ticket</h2><p><?php echo esc_html(get_the_title($event_id)); ?></p><form method="post"><?php wp_nonce_field('uem_begin_payment_'.$event_id,'uem_payment_nonce');foreach($tiers as $i=>$tier):?><label style="display:block;padding:16px;margin:10px 0;border:1px solid #dde3ea;border-radius:10px"><input type="radio" name="ticket_code" value="<?php echo esc_attr($tier['code']); ?>" <?php checked($i,0);?> required><strong><?php echo esc_html($tier['name']);?></strong><span style="float:right"><?php echo esc_html(number_format_i18n((float)$tier['price'],2));?> RON</span></label><?php endforeach;?><button class="uem-btn" style="margin-top:15px" name="uem_begin_payment">Continue to secure card payment</button></form></div><?php return ob_get_clean();}
function uem_render_payment_result(){if(!is_user_logged_in())return '<p>Please log in.</p>';$order=uem_payment_get_order(sanitize_text_field($_GET['order']??''));if(!$order||$order->user_id!=get_current_user_id())return '<p>Payment order not found.</p>';return '<div style="max-width:650px;margin:40px auto;padding:30px;text-align:center;background:#fff;border-radius:16px"><h2>Payment status</h2><p>Your payment is <strong>'.esc_html($order->status).'</strong>.</p>'.($order->status==='paid'?'<a class="uem-btn" href="'.esc_url(get_permalink($order->event_id)).'">Go to event</a>':'<p>Access is activated only after NETOPIA confirms the payment.</p>').'</div>';}
add_shortcode('uem_payment_result','uem_render_payment_result');
